// O teste usa um banco descartável iniciado no setup
// e limpo ao final, garantindo isolamento entre execuções.

describe('PedidoRepository', () => {
  let repository;
  let connection;

  beforeAll(async () => {
    connection = await createTestDatabase();
    repository = new PedidoRepository(connection);
  });

  afterAll(async () => {
    await connection.close();
  });

  it('persiste e recupera um pedido com seus itens', async () => {
    const pedido = new Pedido([
      { produto: 'caneta', preco: 2.5 },
      { produto: 'caderno', preco: 12.0 }
    ]);

    await repository.salvar(pedido);
    const recuperado = await repository.buscarPorId(pedido.id);

    expect(recuperado.itens).toHaveLength(2);
    expect(recuperado.total()).toBe(14.5);
  });
});
